impl Solution {
    pub fn can_cross(a: Vec<u8>, m: usize, k: i64) -> bool {
        let n = a.len();
        let mut dp = vec![i64::MAX; n + 2];
        dp[0] = 0;

        for i in 0..=n {
            for j in i + 1..=n {
                let jump = (j - i) as i64;
                if jump <= m as i64 && dp[i] != i64::MAX {
                    if a[j - 1] == 1 {
                        continue;
                    }
                    dp[j] = dp[j].min(dp[i] + jump);
                }
            }
        }

        dp[n + 1] <= k && dp[n + 1] != i64::MAX
    }
}

